def calculate_n(a, b, c):
    e1 = a + b + c
    e2 = a*b + b*c + c*a
    e3 = a*b*c
    numerator = e1 * (e2 + 1)
    denominator = 4 * e3

    if denominator == 0:
        return None

    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

unique_n = set()
# Search space: 1 <= a < b < c <= 20
for c in range(3, 21):
    for b in range(2, c):
        for a in range(1, b):
            n = calculate_n(a, b, c)
            if n is not None:
                unique_n.add(n)

print("Unique integer values of n found:", sorted(list(unique_n)))
